import {opportunityLabel} from './opportunity-labels.js';
import {studyReviewView} from './study-review.js';
import {feedbackFor} from './agent-context.js';
import {adviceFingerprint} from './journey-state.js';
import {DATA,programFor,coursesFor} from './planner.js';
import {STEPS,suggestMinors} from './guidance.js';
import {selectedMinor} from './minors.js';
import {QUESTIONS,missingAnswers} from './questionnaire.js';
import {questionnaireCard,questionNavigation} from './question-cards.js';
import {EVIDENCE,AXES,evidenceFor,EVIDENCE_REVIEWED} from './evidence.js';
import {esc,btn,options,choiceField,minorChecklistView,experienceCards,targetEvidence,targetSourceLink,link,cite} from './views.js';
const select=(key,title,values,value,kind='profile')=>`<label class="field">${title}<select data-${kind}="${key}">${options(values,value)}</select></label>`;
const input=(key,title,value,type='text',kind='profile')=>`<label class="field">${title}<input data-${kind}="${key}" type="${type}" value="${esc(value)}"></label>`;
const prose=(key,title,value,hint='')=>`<label class="field">${title}<textarea data-journey="${key}" rows="3" maxlength="1800" placeholder="${esc(hint)}">${esc(value||'')}</textarea></label>`;
export const sourceLinks=ids=>evidenceFor(ids).map(s=>link(s.url,s.title+' · '+s.date)).join(' · ');
export function assessmentView(assessment=[],academicSources=[]){return assessment.length?`<details class="reasoning-panel"><summary>Why this combination fits you</summary><div class="reasoning-grid">${assessment.map(a=>`<article><h4>${esc(AXES[a.axis]||a.axis)}</h4><p>${esc(a.explanation)}</p><small>${(a.answerIds||[]).map(id=>'Your answer: '+esc(QUESTIONS.find(q=>q.id===id)?.label||id)).join(' · ')}</small><div class="evidence-links">${a.axis==='academicFit'?'':sourceLinks(a.evidenceIds)}</div></article>`).join('')}</div></details>`:'';}
const agentBox=(title,body,actions='')=>`<section class="advisor-response"><div class="adviser-label"><span class="adviser-mark" aria-hidden="true">G</span><span class="eyebrow">${title}</span></div><p>${esc(body)}</p>${actions}</section>`;
export function journeyView(state,runtime={}){
 const j=state.journey,p=programFor(j.profile),minor=selectedMinor(j.profile),a=j.advice,second=p.tracks.find(t=>t.id===j.profile.secondTrack);let body='';const validation=runtime.validation||{};
 const refine=stage=>updateView(j.lastUpdates?.[stage])+`<label class="field">Tell the agent what to change<textarea data-feedback="${stage}" rows="3" maxlength="1800" placeholder="Describe what you would like to keep, change or understand.">${esc(feedbackFor(j,stage))}</textarea></label>`+`<button class="button secondary" data-agent-stage="${stage}">Update recommendations</button>`;
 if(j.step===0)body=`<h2>First, a little about you.</h2><p class="intro-copy">Start with where you are today. Your adviser will help you explore what comes next.</p>${prose('background','Where are you in your education?',j.background,'For example: I am finishing high school, or I am studying at AUI and considering a new direction.').replace('data-journey="background"',`data-journey="background" aria-invalid="${!!validation.background}" aria-describedby="background-error"`)}<p id="background-error" class="field-error" ${validation.background?'':'hidden'}>Tell us a little about your current education to begin.</p><div class="field-grid">${select('level','Level you are considering',[['undergraduate','Undergraduate'],['graduate','Graduate']],j.level,'journey')}${select('preferredDegree','Degree already in mind',[['undecided','Let the agent help me decide'],...DATA.programs.filter(x=>x.level===j.level).map(x=>[x.id,x.name])],j.preferredDegree,'journey')}${input('name','Your name (optional, stays on this device)',j.profile.name)}${input('startYear','Starting fall year',j.profile.startYear,'number')}</div>${j.setup?agentBox('YOUR STARTING RECOMMENDATION',j.setup.summary,`<p class="small-note">${(j.setup.questions||[]).map(esc).join(' ')}</p><button class="button secondary" data-agent-stage="setup">Reconsider starting point</button>`):'<p class="small-note">Nothing is decided yet. You can change your choices as you go.</p>'}`;
 if(j.step===1)body=questionnaireCard(j,validation)+(a?.kind==='clarify'?agentBox('ONE MORE THING',a.summary+(a.questions||[]).join(' '),prose('answers','Your clarification',j.answers)):'');
 if(j.step===2)body=`<h2>Your proposed direction</h2>${agentBox('RECOMMENDED FOR YOU',a?.summary||'Review the agent recommendation and adjust any choice below.')}<div class="academic-combination"><article class="degree-decision"><span class="eyebrow">YOUR DEGREE</span><h3>${esc(p.name)}</h3><p>${esc(a?.academic?.rationale||'')}</p></article><div class="focus-decisions"><article><span class="eyebrow">PRIMARY FOCUS</span><h3>${esc(p.tracks.find(t=>t.id===j.profile.track)?.name||'Degree focus')}</h3><p>${esc(a?.academic?.focusRationale||'')}</p></article>${second?`<article><span class="eyebrow">SECOND ${p.id==='BBA'?'CONCENTRATION':'SPECIALIZATION'}</span><h3>${esc(second.name)}</h3><p>${esc(a?.academic?.secondFocusRationale||'')}</p></article>`:''}<article><span class="eyebrow">COMPLEMENTARY MINOR</span><h3>${minor?esc(minor.name):'No minor for now'}</h3><p>${esc(a?.academic?.minorRationale||'You can add an eligible minor below.')}</p></article></div></div>${minor?.reviewRequired?'<p class="warning">This minor needs individual academic approval. Any required replacement or unconfirmed course stays open for your adviser.</p>':''}${assessmentView(a?.assessment,[p.source,minor?.source])}${researchView(a?.research,'direction')}${a?.tradeoffs?.length?`<details class="quiet-details"><summary>Trade-offs to consider</summary>${a.tradeoffs.map(t=>`<p class="small-note">${esc(t)}</p>`).join('')}</details>`:''}<details class="choice-group" data-disclosure="academic-choices"><summary>Change the recommended academic choices</summary><div class="field-grid">${select('program','Degree',DATA.programs.filter(x=>x.level===j.level).map(x=>[x.id,x.name]),p.id)}${p.tracks.length?select('track','Major / primary focus',p.tracks.map(t=>[t.id,t.name]),j.profile.track):''}${['BBA','BSCSC'].includes(p.id)?select('secondTrack',p.id==='BBA'?'Second concentration':'Second specialization',[['','None'],...p.tracks.filter(t=>t.id!==j.profile.track).map(t=>[t.id,t.name])],j.profile.secondTrack):''}${p.level==='undergraduate'?select('minor',p.id==='BBA'&&second?'Additional minor (adds study)':'Minor',[['','None / leave open'],...suggestMinors(j).map(x=>[x.minor.id,x.minor.name])],j.profile.minor):''}</div></details><details class="quiet-details"><summary>Ask for a different direction</summary>${refine('direction')}</details>`;
 if(j.step===3){const cs=coursesFor(j.profile).filter(c=>c.choice&&!c.minorId),groups=[...new Set(cs.map(c=>c.category))];body=`<h2>The courses behind your direction</h2>${agentBox('AGENT COURSE SELECTION',j.details?.summary||'Your electives connect your interests to the skills you want to build.')}<p class="small-note">Selections are applied to this draft for your review. A few choices may need placement or adviser confirmation.</p>${(j.details?.reviewNotes||[]).length?`<details class="quiet-details"><summary>${j.details.reviewNotes.length} choices need a follow-up</summary>${j.details.reviewNotes.map(n=>`<p>${esc(n.message)}</p>`).join('')}</details>`:''}${minorChecklistView(j.profile,{editable:true})}${groups.map((g,i)=>`<details class="choice-group" data-disclosure="courses-${esc(g)}"><summary>${esc(g)} <span>${cs.filter(c=>c.category===g&&c.code).length}/${cs.filter(c=>c.category===g).length} selected</span></summary><div class="field-grid">${cs.filter(c=>c.category===g).map(c=>choiceField(c,j.profile)+`<p class="small-note">${esc(j.choiceReasons?.[c.id]||j.details?.openItems?.find(o=>o.requirementId===c.id)?.reason||'Confirm this requirement with your academic adviser.')}</p>`).join('')}</div></details>`).join('')}<details class="quiet-details"><summary>Ask for different courses</summary>${refine('courses')}</details>`;}
 if(j.step===4)body=`<h2>Where this path could take you</h2>${agentBox('EXPERIENCE RECOMMENDATIONS',j.details?.targetSummary||'Targets connect your answers, academic skills and the supplied evidence.')}<p class="small-note">A shortlist to explore. Keep these suggestions or ask for alternatives.</p>${researchView(j.details?.targetResearch,'targets')}<h3>Moroccan Internship Targets</h3>${experienceCards(j.details?.internships||[],j,'internships')}<h3>Exchange institutions to explore</h3>${experienceCards(j.details?.exchanges||[],j,'exchanges')}<p class="small-note">Availability and eligibility need confirmation with the company or ${link('https://oip-exchange.aui.ma/','AUI’s Office of International Programs')}.</p><details class="quiet-details"><summary>Ask for different destinations</summary>${refine('targets')}</details>`;
 if(j.step===5)body=`<h2>Your pace. Your progress. Your plan.</h2>${agentBox('RECOMMENDED STUDY PACE',j.paceAdvice?.summary||'Ask the agent to recommend a pace around your workload and commitments.',`<p>${esc(j.paceAdvice?.reason||'')}</p>${(j.paceAdvice?.actions||[]).map(x=>`<p class="small-note">${esc(x)}</p>`).join('')}`)}<div class="field-grid">${select('regularCourses','Courses per regular semester',p.level==='graduate'?[['4','Up to 4 courses']]:[['5','Up to 5 courses'],['6','Up to 6 courses']],String(j.profile.regularCourses))}${select('summers','Summer study',[['true','Include summer courses'],['false','No summer courses']],String(j.profile.summers))}${j.profile.summers?select('summerCourses','Courses per summer session',p.level==='graduate'?[['2','Up to 2 courses']]:[['2','Up to 2 courses'],['3','Up to 3 courses']],String(j.profile.summerCourses)):''}${input('gpa','CGPA (optional; not shared with AI)',j.profile.gpa,'number')}${select('lc','Language Center semesters still needed',[['0','None / already completed'],['1','One'],['2','Two']],String(j.profile.lc))}</div>${studyReviewView(j)}<details class="quiet-details"><summary>How course loads work</summary><p>Regular and summer loads are independent upper targets. Credit limits, prerequisites and internship timing may reduce a term’s load. Six regular or three summer courses require the applicable academic standing or approval.</p></details><details class="quiet-details"><summary>Adjust with my adviser</summary>${refine('pace')}</details>`;
 const access='';
 const next=j.step===0?(j.setup?'Continue to my goals →':'Review my starting point →'):j.step===1?'Find my direction →':j.step===2?'Continue to courses →':j.step===3?'Explore opportunities →':j.step===4?'Choose my pace →':'Build my roadmap ↗';
 const failure=runtime.aiFailure,blocked=failure?.retryable===false&&failure.fingerprint===adviceFingerprint(failure.stage,j);
 const blockedNext=blocked&&failure.stage===['setup','direction','courses','targets','pace'][j.step];
 const recovery=runtime.researchFailureStage?`<button type="button" class="button secondary" data-research-stage="${esc(runtime.researchFailureStage)}">Retry research only</button>`:blocked?(failure.stage==='courses'?btn('review-course-choices','Review courses manually'):'<p class="small-note">Your answers are saved. This recommendation is unavailable for now; you can review or edit your choices.</p>'):btn('retry-ai','Retry this recommendation');
 return `<section class="journey" aria-busy="${!!runtime.busy}"><div class="journey-top"><span class="eyebrow">STEP ${j.step+1} OF 6 · ${STEPS[j.step]}</span>${state.plan?btn('cancel-journey','Return to saved plan'):''}</div><ol class="journey-steps" aria-label="Planning progress">${STEPS.map((s,i)=>`<li class="${i===j.step?'current':i<j.step?'passed':''}" ${i===j.step?'aria-current="step"':''}><span>${i<j.step?'✓':i+1}</span><small>${s}</small></li>`).join('')}</ol><fieldset class="journey-body" ${runtime.busy?'disabled':''}>${j.changeRequest?`<details class="change-context"><summary>Updating your plan</summary><p>${esc(j.changeRequest)}</p><p>Your saved plan stays in place until you accept the update.</p></details>`:''}${body}<div class="ask-adviser-row">${btn('ask-adviser','Ask about this step')}</div>${access}${runtime.aiStatus?.available===false?'<p class="warning">The AI connection is unavailable. Your draft is saved; reconnect to continue with agent recommendations.</p>':''}${runtime.aiError?`<div class="warning" role="alert">${esc(runtime.aiError)}<div class="card-actions">${recovery}</div></div>`:''}${runtime.busy?'<p class="ai-working" role="status"><span class="working-spinner" aria-hidden="true"></span><span><strong>Checking your plan and supporting sources</strong><small>Your answers are saved. Research checks keep your existing choices in place.</small></span></p>':''}</fieldset><div class="journey-actions">${j.step===1&&!runtime.busy?questionNavigation(j):`${j.step?`<button type="button" class="button secondary" data-action="journey-back" ${runtime.busy?'disabled':''}>← Back</button>`:'<span class="journey-saved-note">Your answers save as you go</span>'}<button class="button primary" data-action="${j.step===5?'build-roadmap':'journey-next'}" ${runtime.busy||blockedNext?'disabled':''}>${next}</button>`}</div></section>`;
}

export function roadmapInsights(plan){return `<section class="roadmap-direction"><div class="section-heading"><h2>Beyond the classroom</h2>${btn('agent-targets','Refine targets')}</div><div class="roadmap-targets">${['internships','exchanges'].map(type=>`<section class="panel"><span class="eyebrow">${type==='internships'?'MOROCCAN COMPANIES':'EXCHANGE DESTINATIONS'}</span>${(plan.targets?.[type]||[]).map((t,i)=>`<article class="roadmap-target"><h3>${esc(t.name)}</h3>${t.organizationType||t.country?`<small>${esc(opportunityLabel(t,type))}</small>`:''}<p>${esc(t.reason)}</p><div class="evidence-links">${targetSourceLink(t)}</div><details data-disclosure="target-${type}-${i}"><summary>Explore this match</summary><p>${esc(t.industryReason||t.tierReason||'')}</p>${targetEvidence(t)}<p class="small-note">${esc((Array.isArray(t.constraints)?t.constraints.join(' '):t.constraints)||t.caveat||'Check current openings, eligibility and dates.')}</p>${link(t.sourceUrl,'Learn more')}</details></article>`).join('')||'<p class="small-note target-empty">Your adviser can suggest a shortlist. Choose “Refine targets” to explore options.</p>'}</section>`).join('')}</div></section>`;}

export function updateView(update){if(!update)return '';return `<section class="info-box" aria-label="Recommendation update"><strong>How your feedback changed the plan</strong><p>${esc(update.summary)}</p>${update.added?.length?`<p><b>Added:</b> ${update.added.map(esc).join(', ')}</p>`:''}${update.removed?.length?`<p><b>Replaced:</b> ${update.removed.map(esc).join(', ')}</p>`:''}${(update.changes||[]).map(x=>`<p>${esc(x)}</p>`).join('')}${(update.limitations||[]).map(x=>`<p class="small-note"><b>Still unresolved:</b> ${esc(x)}</p>`).join('')}</section>`;}
export function researchView(research,stage=''){
 if(!research||research.status==='not-requested')return '';
 const retry=['direction','targets'].includes(stage)?`<div class="card-actions"><button type="button" class="button secondary" data-research-stage="${stage}">Research again</button></div><p class="small-note">Checks missing evidence. Your academic choices and shortlist stay in place.</p>`:'';
 const warning=['unavailable','partial'].includes(research.status)?`<div class="warning"><p>${esc(research.notice)}</p>${retry}</div>`:'';
 if(research.status==='unavailable')return warning;
 return warning+`<details class="reasoning-panel"><summary>Research behind these suggestions</summary><p>${esc(research.summary)}</p>${(research.gaps||[]).map(g=>`<p class="small-note">${esc(g)}</p>`).join('')}${(research.facts||[]).map(f=>`<p>${esc(f.claim)} ${link(f.url,'Source')}</p><p class="small-note">${esc(f.limitation)}</p>`).join('')}<div class="evidence-links">${(research.sources||[]).map(s=>link(s.url,s.title)).join(' · ')}</div><p class="small-note">Research supports the recommendation; it does not establish current vacancies, admissions or exchange eligibility.</p></details>`;
}
